From 66d3351ffd9fd2cd7a3fea7147f4d8318cd904ed Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 19:27:53 +0100
Subject: [PATCH] Positioner: place new files before partial downloads

Browsers create a partial download file before or next to the final one,
so its spot on the desktop turned into a gap once the download finished.
New items now take the earliest spot held by a partial download instead.

BUG: 495319
---
 .../desktop/plugins/folder/positioner.cpp     | 52 ++++++++++++++++++-
 .../desktop/plugins/folder/positioner.h       |  2 +
 2 files changed, 52 insertions(+), 2 deletions(-)

diff --git a/containments/desktop/plugins/folder/positioner.cpp b/containments/desktop/plugins/folder/positioner.cpp
index 8fc7ec4c6c..25c76a8790 100644
--- a/containments/desktop/plugins/folder/positioner.cpp
+++ b/containments/desktop/plugins/folder/positioner.cpp
@@ -750,8 +750,6 @@ void Positioner::sourceLayoutAboutToBeChanged(const QList<QPersistentModelIndex>
 void Positioner::sourceRowsInserted(const QModelIndex &parent, int first, int last)
 {
     Q_UNUSED(parent)
-    Q_UNUSED(first)
-    Q_UNUSED(last)

     if (!m_ignoreNextTransaction) {
         if (m_beginInsertRowsCalled) {
@@ -764,6 +762,16 @@ void Positioner::sourceRowsInserted(const QModelIndex &parent, int first, int la

     flushPendingChanges(true);

+    if (m_enabled && !m_deferApplyPositions) {
+        for (int i = first; i <= last; ++i) {
+            const auto [newRow, oldRow] = placeBeforePartialDownloads(i);
+            if (newRow != -1) {
+                Q_EMIT dataChanged(index(newRow, 0), index(newRow, 0));
+                Q_EMIT dataChanged(index(oldRow, 0), index(oldRow, 0));
+            }
+        }
+    }
+
     // Don't generate new positions data if we're waiting for listing to
     // complete to apply initial positions.
     if (!m_deferApplyPositions && screenInUse()) {
@@ -872,6 +880,45 @@ int Positioner::lastRow() const
     return 0;
 }

+bool Positioner::isPartialDownload(int sourceRow) const
+{
+    static const QStringList suffixes{u".part"_s, u".crdownload"_s, u".partial"_s, u".download"_s, u".opdownload"_s, u".!qb"_s, u".!ut"_s};
+
+    const QString name = m_folderModel->data(m_folderModel->index(sourceRow, 0), FolderModel::UrlRole).toUrl().fileName();
+
+    return std::ranges::any_of(suffixes, [&name](const QString &suffix) {
+        return name.endsWith(suffix, Qt::CaseInsensitive);
+    });
+}
+
+QPair<int, int> Positioner::placeBeforePartialDownloads(int sourceRow)
+{
+    // Partial downloads disappear once finished, so a newly placed item takes
+    // the earliest of their spots instead of leaving a gap behind them.
+    const int row = m_sourceToProxy.value(sourceRow, -1);
+
+    if (row == -1 || isPartialDownload(sourceRow)) {
+        return {-1, -1};
+    }
+
+    int partialRow = -1;
+
+    for (auto it = m_proxyToSource.cbegin(); it != m_proxyToSource.cend(); ++it) {
+        if (it.key() < row && (partialRow == -1 || it.key() < partialRow) && isPartialDownload(it.value())) {
+            partialRow = it.key();
+        }
+    }
+
+    if (partialRow == -1) {
+        return {-1, -1};
+    }
+
+    updateMaps(row, m_proxyToSource.value(partialRow));
+    updateMaps(partialRow, sourceRow);
+
+    return {partialRow, row};
+}
+
 int Positioner::firstFreeRow() const
 {
     if (!m_proxyToSource.isEmpty()) {
@@ -964,6 +1011,7 @@ void Positioner::convertFolderModelData()
         }

         updateMaps(index, it.value());
+        placeBeforePartialDownloads(it.value());
     }

     endResetModel();
diff --git a/containments/desktop/plugins/folder/positioner.h b/containments/desktop/plugins/folder/positioner.h
index 19c1db7f24..abb65971b9 100644
--- a/containments/desktop/plugins/folder/positioner.h
+++ b/containments/desktop/plugins/folder/positioner.h
@@ -151,6 +151,8 @@ private:
     int firstRow() const;
     int lastRow() const;
     int firstFreeRow() const;
+    bool isPartialDownload(int sourceRow) const;
+    QPair<int, int> placeBeforePartialDownloads(int sourceRow);
     // Converts data from folderModel to proxy data
     void convertFolderModelData();
     // Turns proxyToSource data into positions QStringList
